	headerLines := caddyhttp.LoggableStringArray{in.String}
	originRequest := headerLines.HTTPRequest()
	cookieHeaderValues := originRequest.Header["Cookie"]
	if len(cookieHeaderValues) == 0 {
		cookieHeaderValues = []string{originRequest.Header.Get("Cookie")}
	}

	cookies := make([]*http.Cookie, 0, len(cookieHeaderValues))
	for lineIndex := 0; lineIndex < len(cookieHeaderValues); lineIndex++ {
		line := strings.TrimSpace(cookieHeaderValues[lineIndex])
		remaining := line
		for len(remaining) > 0 {
			separator := strings.IndexByte(remaining, ';')
			part := remaining
			if separator >= 0 {
				part = remaining[:separator]
				remaining = remaining[separator+1:]
			} else {
				remaining = ""
			}

			part = strings.TrimSpace(part)
			if part == "" {
				continue
			}

			equals := strings.IndexByte(part, '=')
			name := part
			val := ""
			if equals >= 0 {
				name = part[:equals]
				val = part[equals+1:]
			}
			if name == "" {
				continue
			}
			if strings.ContainsAny(name, " 	()<>@,;:\\\"/[]?={}") {
				continue
			}

			if len(val) >= 2 && val[0] == '"' && val[len(val)-1] == '"' {
				val = val[1 : len(val)-1]
			}

			valueOK := true
			for valueIndex := 0; valueIndex < len(val); valueIndex++ {
				b := val[valueIndex]
				if b < 0x20 || b >= 0x7f || b == '"' || b == ';' || b == '\\' {
					valueOK = false
					break
				}
			}
			if !valueOK {
				continue
			}

			parsed := new(http.Cookie)
			parsed.Name = name
			parsed.Value = val
			parsed.Path = ""
			parsed.Domain = ""
			parsed.Raw = part
			parsed.HttpOnly = false
			parsed.Secure = false
			parsed.Unparsed = nil
			cookies = append(cookies, parsed)
		}
	}

	hexdigits := "0123456789abcdef"
	transformedHeader := make(http.Header)
	transformedRequest := http.Request{}
	transformedRequest.Header = transformedHeader
	for cookieIndex := 0; cookieIndex < len(cookies); cookieIndex++ {
		cookie := cookies[cookieIndex]
		if cookie == nil || cookie.Name == "" {
			continue
		}

		current := http.Cookie{}
		current.Name = cookie.Name
		current.Value = cookie.Value
		current.Path = cookie.Path
		current.Domain = cookie.Domain
		current.Raw = cookie.Raw
		current.HttpOnly = cookie.HttpOnly
		current.Secure = cookie.Secure

		applied := false
		for actionIndex := 0; actionIndex < len(m.Actions); actionIndex++ {
			action := m.Actions[actionIndex]
			if action.Name == "" || current.Name != action.Name {
				continue
			}
			if err := action.Type.IsValid(); err != nil {
				continue
			}

			switch action.Type {
			case replaceAction:
				current.Value = action.Value
				transformedRequest.AddCookie(&current)
				applied = true

			case hashAction:
				payload := []byte(current.Value)
				sum := sha256.Sum256(payload)
				var hashed strings.Builder
				hashed.Grow(8)
				for digestIndex := 0; digestIndex < len(sum); digestIndex++ {
					if digestIndex >= 4 {
						break
					}
					high := sum[digestIndex] >> 4
					low := sum[digestIndex] & 0x0f
					nibble := [2]byte{}
					nibble[0] = hexdigits[high]
					nibble[1] = hexdigits[low]
					hashed.Write(nibble[:])
				}
				current.Value = hashed.String()
				transformedRequest.AddCookie(&current)
				applied = true

			case deleteAction:
				applied = true
			}

			if applied {
				break
			}
		}

		if !applied {
			transformedRequest.AddCookie(&current)
		}
	}

	encoded := transformedRequest.Header.Get("Cookie")
	if encoded == "" {
		encoded = strings.Join(transformedRequest.Header["Cookie"], "; ")
	}
